import hashlib
import hmac
import json

from fastapi import APIRouter, BackgroundTasks, Body, Depends, Header, HTTPException, Request
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from app.config import settings
from app.db import get_db
from app.models import Repository, WorkflowFailure, utc_now
from app.pipeline import run_failure_pipeline_from_settings
from app.pull_request import AUTO_FIX_BRANCH_PREFIX, record_pull_request_event
from app.schemas import FailureListItem, GithubWebhookPayload, WebhookAck

router = APIRouter(prefix="/api/github", tags=["github"])


def extract_workflow_context(payload: dict) -> dict:
    repo_payload = payload.get("repository") or {}
    workflow_payload = payload.get("workflow_run") or {}

    return {
        "repo_id": repo_payload.get("id"),
        "repo_full_name": repo_payload.get("full_name"),
        "repo_default_branch": repo_payload.get("default_branch"),
        "run_id": workflow_payload.get("id"),
        "run_name": workflow_payload.get("name"),
        "run_status": workflow_payload.get("status"),
        "conclusion": workflow_payload.get("conclusion"),
        "head_branch": workflow_payload.get("head_branch"),
    }


def verify_github_signature(payload: bytes, signature_256: str | None) -> None:
    if not settings.github_webhook_secret:
        return

    if not signature_256:
        raise HTTPException(status_code=401, detail="Missing GitHub signature")

    expected = "sha256=" + hmac.new(
        settings.github_webhook_secret.encode("utf-8"),
        payload,
        hashlib.sha256,
    ).hexdigest()

    if not hmac.compare_digest(expected, signature_256):
        raise HTTPException(status_code=401, detail="Invalid GitHub signature")


def get_or_create_repository(db: Session, repo_payload: dict) -> Repository:
    repo_id = repo_payload.get("id") or repo_payload.get("repo_id")
    full_name = repo_payload.get("full_name")
    default_branch = repo_payload.get("default_branch")

    if not full_name:
        raise HTTPException(status_code=400, detail="Missing repository.full_name")

    if repo_id is not None:
        repo = db.query(Repository).filter(Repository.github_repo_id == repo_id).first()
        if repo:
            repo.full_name = full_name
            repo.default_branch = default_branch
            db.flush()
            return repo

    repo = db.query(Repository).filter(Repository.full_name == full_name).first()
    if repo:
        if repo_id is not None:
            repo.github_repo_id = repo_id
        repo.default_branch = default_branch
        db.flush()
        return repo

    repo = Repository(
        github_repo_id=repo_id,
        full_name=full_name,
        default_branch=default_branch,
        created_at=utc_now(),
    )
    db.add(repo)
    db.flush()
    return repo

@router.post("/webhook", response_model=WebhookAck)
async def github_webhook(
    request: Request,
    background_tasks: BackgroundTasks,
    payload: GithubWebhookPayload = Body(...),
    db: Session = Depends(get_db),
    x_github_event: str | None = Header(default=None, alias="X-GitHub-Event"),
    x_hub_signature_256: str | None = Header(default=None, alias="X-Hub-Signature-256"),
):
    raw_body = await request.body()
    if not raw_body:
        raise HTTPException(status_code=400, detail="Request body is empty")

    verify_github_signature(raw_body, x_hub_signature_256)

    event_name = (x_github_event or "unknown").strip().lower()

    if event_name == "ping":
        return WebhookAck(
            accepted=True,
            message="GitHub webhook is reachable",
        )

    if event_name == "pull_request":
        body = json.loads(raw_body)
        pr = body.get("pull_request") or {}
        recorded = record_pull_request_event(
            db,
            action=body.get("action"),
            merged=bool(pr.get("merged")),
            html_url=pr.get("html_url"),
            head_ref=(pr.get("head") or {}).get("ref") or "",
        )
        return WebhookAck(
            accepted=True,
            message="Pull request outcome recorded" if recorded else "Pull request event ignored",
        )

    if event_name != "workflow_run":
        return WebhookAck(
            accepted=True,
            message=f"Ignored event: {event_name}",
        )

    if payload.repository is None:
        raise HTTPException(
            status_code=400,
            detail="repository payload is missing",
        )

    if payload.workflow_run is None:
        raise HTTPException(
            status_code=400,
            detail="workflow_run payload is missing",
        )

    context = extract_workflow_context(payload.model_dump())
    run_id = context["run_id"]
    run_name = context["run_name"]
    run_status = context["run_status"]
    conclusion = (context["conclusion"] or "").strip().lower()
    head_branch = context["head_branch"]

    if run_id is None:
        raise HTTPException(
            status_code=400,
            detail="workflow_run.id is missing",
        )

    if run_name is None:
        raise HTTPException(
            status_code=400,
            detail="workflow_run.name is missing",
        )

    if run_status is None:
        raise HTTPException(
            status_code=400,
            detail="workflow_run.status is missing",
        )

    print(
        f"GitHub event={event_name!r}, "
        f"run_id={run_id!r}, "
        f"conclusion={conclusion!r}"
    )

    try:
        repo_payload = {
            "id": context["repo_id"],
            "full_name": context["repo_full_name"],
            "default_branch": context["repo_default_branch"],
        }
        repo = get_or_create_repository(db, repo_payload)

        # Runs on our own fix branches come from opening a draft PR. Analyzing them
        # would open another PR, so they are never stored.
        if (head_branch or "").startswith(AUTO_FIX_BRANCH_PREFIX):
            db.commit()
            return WebhookAck(
                accepted=True,
                message=f"Ignored run on auto-fix branch {head_branch}",
            )

        if conclusion != "failure":
            db.commit()
            return WebhookAck(
                accepted=True,
                message=(
                    "Workflow received but not stored as a failure; "
                    f"conclusion={conclusion or 'null'}"
                ),
            )

        failure = (
            db.query(WorkflowFailure)
            .filter(WorkflowFailure.github_run_id == run_id)
            .first()
        )

        if failure:
            failure.repository_id = repo.id
            failure.workflow_name = run_name
            failure.branch = head_branch
            failure.conclusion = conclusion
            failure.status = run_status
            failure.error_summary = (
                "Failure captured; log analysis pending."
            )
        else:
            failure = WorkflowFailure(
                github_run_id=run_id,
                repository_id=repo.id,
                workflow_name=run_name,
                branch=head_branch,
                conclusion=conclusion,
                status=run_status,
                error_summary=(
                    "Failure captured; log analysis pending."
                ),
                created_at=utc_now(),
            )
            db.add(failure)

        db.commit()
        db.refresh(failure)

        if settings.github_token:
            background_tasks.add_task(run_failure_pipeline_from_settings, failure.id)

        return WebhookAck(
            accepted=True,
            message=(
                "Failure stored successfully; "
                f"failure_id={failure.id}, run_id={run_id}"
            ),
        )

    except IntegrityError as e:
        db.rollback()
        raise HTTPException(
            status_code=409,
            detail=str(e.orig),
        )


@router.get("/failures", response_model=list[FailureListItem])
def list_failures(db: Session = Depends(get_db)):
    rows = (
        db.query(WorkflowFailure, Repository)
        .outerjoin(Repository, WorkflowFailure.repository_id == Repository.id)
        .filter(WorkflowFailure.conclusion == "failure")
        .order_by(WorkflowFailure.created_at.desc())
        .limit(50)
        .all()
    )

    return [
        FailureListItem(
            id=failure.id,
            repo_name=repo.full_name if repo else "unknown",
            workflow_name=failure.workflow_name,
            branch=failure.branch,
            conclusion=failure.conclusion,
            status=failure.status,
            error_summary=failure.error_summary,
            created_at=failure.created_at,
        )
        for failure, repo in rows
    ]
